package com.mamtrex.hospital.appointment;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/appointments") public class AppointmentController { private final AppointmentRepository repo; private final AuditService audit; public AppointmentController(AppointmentRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String professionalId, @jakarta.validation.constraints.NotBlank String scheduledAt, @jakarta.validation.constraints.NotBlank String type, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public Appointment create(@Valid @RequestBody Request r){var e=repo.save(new Appointment(r.patientId(), r.professionalId(), r.scheduledAt(), r.type(), r.status()));audit.record("CREATE","Appointment",e.getId().toString(),"created");return e;} @GetMapping public List<Appointment> list(){return repo.findAll();} @GetMapping("/{id}") public Appointment get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Appointment not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Appointment not found: "+id);repo.deleteById(id);audit.record("DELETE","Appointment",id.toString(),"deleted");} }
